import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.environ.get("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def post(path, payload):
    response = session.post(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json() if response.content else {}


def put(path, payload):
    response = session.put(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json() if response.content else {}


def patch(path, payload):
    response = session.patch(f"{BASE_URL}{path}", json=payload, timeout=30)
    response.raise_for_status()
    return response.json() if response.content else {}


# Supply identifiers and payloads for the target resource, repository, and application.
resource_id = os.environ["RESOURCE_ID"]
repository_id = os.environ["REPOSITORY_ID"]

scan = post("/scan/network", {
    "scope": "system",
    "purpose": "detect vulnerabilities",
})

scan_id = scan.get("scan_id") or scan.get("id")
if not scan_id:
    raise RuntimeError("Network scan response did not include a scan identifier.")

# Use the scan findings to inform these configuration and performance updates.
resource_update = patch(
    f"/infrastructure/resources/{resource_id}",
    {
        "configuration": {
            "security_hardening": True,
            "performance_optimization": True,
            "scan_id": scan_id,
        }
    },
)

scaling_policy = post("/scaling/policies", {
    "name": "vulnerability-response-scaling",
    "conditions": {
        "scan_id": scan_id,
        "purpose": "dynamically manage resources based on scan outcomes",
    },
    "actions": {
        "scale_out_on_remediation_load": True,
        "scale_in_after_remediation": True,
    },
})

branch = post(f"/repositories/{repository_id}/branches", {
    "name": f"vulnerability-fixes-{scan_id}",
    "source_branch": "main",
    "description": "Track changes for vulnerability fixes and resource updates",
})

application = post("/application/register", {
    "name": "Vulnerability Remediation Manager",
    "description": "Manage access control for identified vulnerabilities and infrastructure updates",
    "purpose": "vulnerability remediation and resource update access management",
})

result = {
    "scan": scan,
    "resource_update": resource_update,
    "scaling_policy": scaling_policy,
    "branch": branch,
    "application": application,
}

