import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Content-Type": "application/json"})

transaction_response = session.post(
    f"{BASE_URL}/transactions",
    json={
        "property_id": "PROPERTY_ID",
        "client_id": "CLIENT_ID",
        "details": {
            "transaction_type": "purchase",
            "price": 500000,
            "currency": "USD",
            "parties": ["CLIENT_ID"],
            "notes": "Capture all transaction details and required documentation."
        }
    },
)
transaction_response.raise_for_status()
transaction = transaction_response.json()
transaction_id = transaction.get("id") or transaction.get("transaction_id")
if not transaction_id:
    raise ValueError("Transaction response did not include a transaction ID.")

report_response = session.post(
    f"{BASE_URL}/custom-reports",
    json={
        "transaction_id": transaction_id,
        "criteria": {
            "geographic_area": "SPECIFIC_AREA",
            "property_type": "residential",
            "analysis_preferences": ["market_value", "recent_sales", "market_trends"]
        }
    },
)
report_response.raise_for_status()
report = report_response.json()

feedback_response = session.post(
    f"{BASE_URL}/tours/TOUR_ID/feedback",
    json={
        "property_id": "PROPERTY_ID",
        "feedback": "TOUR_FEEDBACK",
        "rating": 5
    },
)
feedback_response.raise_for_status()
feedback = feedback_response.json()

finalize_response = session.post(
    f"{BASE_URL}/transactions/{transaction_id}/finalize",
    json={
        "custom_report": report,
        "tour_feedback": feedback,
        "finalization_details": {
            "property_id": "PROPERTY_ID",
            "client_id": "CLIENT_ID",
            "transaction_details": transaction.get("details", {}),
            "documents_archived": True
        }
    },
)
finalize_response.raise_for_status()
finalized_transaction = finalize_response.json()
